tree_node *char_tree::copy(tree_node *x, tree_node *p)
{
    tree_node *top = clone_node(x);
    top->parent = p;
    if (x->right)
        top->right = copy(x->right, top);
    p = top;
    x = x->left;
    while (x != 0) {
        tree_node *y = clone_node(x);
        p->left = y;
        y->parent = p;
        if (x->right)
            y->right = copy(x->right, y);
        p = y;
        x = x->left;
    }
    return top;
}
